import {accountsEnabled,refreshAccountHeader} from './account-header.js';
import {agendaImages} from './agenda-images.js';
import {agenda,agendaMeta} from './agenda-data.js';
import {localDate,eventState,occursOn,inMonth,isNow,TIME_ZONE} from './agenda-time.js';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),norm=s=>String(s).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
let lang='es';try{lang=sessionStorage.getItem('lavita-language')==='en'?'en':'es';}catch{}
let plan='all';
let mode='now',chosenDay='',limit=24,lastFocus;const dialog=$('#agenda-dialog');
const words={es:{socialite:'Socialité',stays:'Alojamientos',foodFilter:'Comida',entertainmentFilter:'Entretenimiento',partyFilter:'Party',artFilter:'Arte',topicLabel:'Filtrar por plan',poster:'Imagen del evento',artistPhoto:'Imagen del artista',imageSource:'Imagen publicada por',viewImage:'Ver imagen completa',title:'Sucediendo ahora',explore:'Explorar',guides:'Guías',intro:'Roma · Condesa · Chapultepec',now:'Ahora',today:'Hoy',nov:'Noviembre',dec:'Diciembre',search:'Busca un evento, artista o recinto…',category:'Tipo de plan',venue:'Recinto',area:'Zona',all:'Todos',barrio:'Roma–Condesa',chapultepec:'Chapultepec',music:'Música',theatre:'Teatro',film:'Cine',meetup:'Comunidad',art:'Arte y cultura',comedy:'Comedia',talk:'Charlas y encuentros',window:'En horario programado',approx:'En horario · fin aproximado',usual:'Horario habitual',doors:'Acceso según agenda',upcoming:'Por comenzar',started:'Inicio anunciado · confirma con el recinto','door-announcement':'Apertura anunciada · show sin horario',unknown:'Horario por confirmar',future:'Próximamente',past:'Fecha pasada',ended:'Horario transcurrido',season:'Temporada',postponed:'Reprogramado',liveHeading:'En horario ahora',later:'Hoy también',noLive:'Sin actividades con horario vigente confirmado.',noLiveText:'Consulta la agenda de hoy y las próximas fechas.',noToday:'No hay eventos publicados para hoy en esta agenda.',empty:'No hay resultados con estos filtros.',published:'fechas y funciones publicadas',according:'Según horarios publicados · no es una transmisión en vivo.',review:'Agenda revisada el 11 nov 2026',refresh:'El día y los estados cambian automáticamente con la hora de CDMX. Las nuevas publicaciones del organizador requieren actualizar la agenda.',coverage:'Fuentes y cobertura',more:'Ver más',reset:'Limpiar filtros',allMonth:'Todo el mes',selected:'Agenda del',doorsLabel:'Puertas',show:'Inicio',end:'Hasta',approxEnd:'Fin aproximado',pending:'Horario no publicado',source:'Consultar evento y disponibilidad',sources:'Fuentes',checked:'Consultado el',close:'Cerrar',free:'Entrada libre',soldout:'Agotado según publicación',registered:'Registro cerrado',details:'Ver detalles',back:'Volver a explorar',calendar:'Calendario del mes',snapshot:'Carteleras publicadas de los recintos consultados; no incluye eventos privados ni anuncios aún no publicados. Diciembre se amplía conforme se anuncian nuevas fechas.',noFiction:'Agenda real · sin cupones ficticios',outside:'Agenda disponible: noviembre y diciembre de 2026.',price:'Precio publicado',timeNote:'Horario de Ciudad de México. Confirma cambios y acceso en la fuente.',profile:'Tu perfil demo',points:'puntos de ejemplo',function:'función',functions:'funciones',seasonNote:'Temporada; consulta días y horarios de visita.',usualNote:'Horario habitual del recinto; confirma días festivos.',approxNote:'El fin se calcula a partir de la duración aproximada publicada por el recinto.'},en:{socialite:'Socialité',stays:'Stays',foodFilter:'Food',entertainmentFilter:'Entertainment',partyFilter:'Party',artFilter:'Art',topicLabel:'Filter by plan',poster:'Event image',artistPhoto:'Artist image',imageSource:'Image published by',viewImage:'View full image',title:'Happening now',explore:'Explore',guides:'Guides',intro:'Roma · Condesa · Chapultepec',now:'Now',today:'Today',nov:'November',dec:'December',search:'Search an event, artist or venue…',category:'Event type',venue:'Venue',area:'Area',all:'All',barrio:'Roma–Condesa',chapultepec:'Chapultepec',music:'Music',theatre:'Theater',film:'Film',meetup:'Community',art:'Art & culture',comedy:'Comedy',talk:'Talks & gatherings',window:'Within scheduled hours',approx:'Scheduled · approximate end',usual:'Regular opening hours',doors:'Scheduled admission',upcoming:'Coming up',started:'Announced start · check with venue','door-announcement':'Doors announced · show time unavailable',unknown:'Time to be confirmed',future:'Upcoming',past:'Past date',ended:'Scheduled hours elapsed',season:'Season',postponed:'Rescheduled',liveHeading:'Scheduled right now',later:'Also today',noLive:'No activities with confirmed current time windows.',noLiveText:'Browse today’s agenda and the upcoming dates.',noToday:'No events published for today in this agenda.',empty:'No results match these filters.',published:'published dates and performances',according:'Based on published schedules · not a live broadcast.',review:'Agenda checked Nov 11, 2026',refresh:'The date and statuses change automatically with Mexico City time. New organizer announcements require an agenda update.',coverage:'Sources & coverage',more:'Show more',reset:'Clear filters',allMonth:'Whole month',selected:'Agenda for',doorsLabel:'Doors',show:'Starts',end:'Until',approxEnd:'Approximate end',pending:'Time not published',source:'View event & availability',sources:'Sources',checked:'Checked on',close:'Close',free:'Free admission',soldout:'Listed as sold out',registered:'Registration closed',details:'View details',back:'Back to explore',calendar:'Monthly calendar',snapshot:'Published schedules from the venues reviewed; excludes private events and unpublished announcements. December expands as new dates are announced.',noFiction:'Real agenda · no demo coupons',outside:'Agenda available: November and December 2026.',price:'Published price',timeNote:'Mexico City time. Confirm changes and admission with the source.',profile:'Your demo profile',points:'demo points',function:'performance',functions:'performances',seasonNote:'Season; check visiting days and hours.',usualNote:'Regular venue hours; confirm public holidays.',approxNote:'End time is calculated from the approximate duration published by the venue.'}};
const tr=k=>words[lang][k]||k;const locale=()=>lang==='en'?'en-US':'es-MX';
function dateText(day,full=false){return new Intl.DateTimeFormat(locale(),{timeZone:TIME_ZONE,day:'numeric',month:full?'long':'short',...(full?{weekday:'long',year:'numeric'}:{})}).format(new Date(day+'T12:00:00-06:00'));}
function schedule(e){return [e.doorsTime?`${tr('doorsLabel')} ${e.doorsTime}`:'',e.startTime?`${tr('show')} ${e.startTime}`:'',e.endTime?`${tr(e.endApproximate?'approxEnd':'end')} ${e.endTime}`:''].filter(Boolean).join(' · ')||tr('pending');}
function member(){try{const p=JSON.parse(sessionStorage.getItem('lavita-community-demo'));if(p&&typeof p.name==='string'&&Number.isFinite(p.points))return p;}catch{}return {name:'Sofía',points:1250};}
function interfaceText(){document.documentElement.lang=lang;document.title=tr('title')+' · La Vita';document.querySelectorAll('[data-i18n]').forEach(e=>e.textContent=tr(e.dataset.i18n));$('#language').value=lang;$('#agenda-search').placeholder=tr('search');$('#agenda-search').setAttribute('aria-label',tr('search'));$('#close-agenda').setAttribute('aria-label',tr('close'));$('#calendar').setAttribute('aria-label',tr('calendar'));if(accountsEnabled){refreshAccountHeader();}else{const p=member();$('#profile-name').textContent=p.name;$('#profile-points').textContent=new Intl.NumberFormat(locale()).format(p.points)+' pts · Demo';$('.avatar').textContent=p.name.slice(0,1);}const keep={type:$('#agenda-type').value,venue:$('#agenda-venue').value,area:$('#agenda-area').value};$('#agenda-type').innerHTML=`<option value="">${tr('all')}</option>`+[...new Set(agenda.map(e=>e.category))].sort().map(k=>`<option value="${k}">${tr(k)}</option>`).join('');$('#agenda-venue').innerHTML=`<option value="">${tr('all')}</option>`+[...new Set(agenda.map(e=>e.venue))].sort().map(v=>`<option>${esc(v)}</option>`).join('');$('#agenda-area').innerHTML=`<option value="">${tr('all')}</option><option value="barrio">${tr('barrio')}</option><option value="chapultepec">${tr('chapultepec')}</option>`;$('#agenda-type').value=keep.type;$('#agenda-venue').value=keep.venue;$('#agenda-area').value=keep.area;render();}
const partyEvents=new Set(['Mitú','Six Sex presenta Ultra','Disco Bahía','Saturnalia: Sonido Gallo Negro y Frente Cumbiero','Easykid']);
function matchesPlan(e){const tags=e.tags||[];if(plan==='all')return true;if(tags.includes(plan))return true;if(plan==='food')return e.category==='food';if(plan==='entertainment')return ['film','theatre','comedy','meetup'].includes(e.category);if(plan==='party')return e.category==='party'||partyEvents.has(e.name);if(plan==='music')return e.category==='music';if(plan==='art')return ['art','theatre'].includes(e.category);return false;}
function filtered(){const q=norm($('#agenda-search').value),type=$('#agenda-type').value,venue=$('#agenda-venue').value,area=$('#agenda-area').value;return agenda.filter(e=>matchesPlan(e)&&(!q||norm(e.name+' '+e.venue+' '+e.area).includes(q))&&(!type||e.category===type)&&(!venue||e.venue===venue)&&(!area||e.scope===area));}
function preview(e,large=false){const p=agendaImages[e.name];if(!p)return '';const alt=tr(p.kind==='artist'?'artistPhoto':'poster')+' · '+e.name;return large?`<figure class="agenda-poster-full"><a href="${esc(p.original)}" target="_blank" rel="noopener noreferrer" aria-label="${tr('viewImage')}"><img src="${esc(p.local)}" alt="${esc(alt)}" decoding="async" width="${p.width}" height="${p.height}"></a><figcaption>${tr('imageSource')} <a href="${esc(p.source)}" target="_blank" rel="noopener noreferrer">${esc(new URL(p.source).hostname.replace('www.',''))} ↗</a></figcaption></figure>`:`<span class="agenda-preview"><img src="${esc(p.local)}" alt="${esc(alt)}" loading="lazy" decoding="async" width="${p.width}" height="${p.height}"></span>`;}
function card(e,now){const state=eventState(e,now),live=isNow(e,now),day=e.through?tr('season'):dateText(e.date);return `<article class="agenda-card ${live?'agenda-current':''}"><button class="agenda-card-open" data-event="${e.id}" aria-label="${esc(e.name)} · ${tr('details')}">${preview(e)}<div class="agenda-card-info"><span class="agenda-card-date">${esc(day)} · ${tr(e.category)}</span><span class="agenda-status ${live?'is-current':''}">${live?'<i class="rec-dot" aria-hidden="true"></i>':''}${tr(state)}</span><h3>${esc(e.name)}</h3><p>${esc(e.venue)} · ${esc(e.area)}</p><strong class="agenda-hours">${esc(schedule(e))}</strong>${e.through?`<small>${dateText(e.date)} — ${dateText(e.through)}</small>`:''}${e.availability==='soldout'?`<small class="agenda-availability">${tr('soldout')}</small>`:e.availability==='registration-closed'?`<small class="agenda-availability">${tr('registered')}</small>`:''}</div><span class="agenda-arrow" aria-hidden="true">↗</span></button></article>`;}
function calendar(list){if(!mode.startsWith('2026-')){$('#calendar').hidden=true;return;}$('#calendar').hidden=false;const [year,month]=mode.split('-').map(Number),days=new Date(Date.UTC(year,month,0)).getUTCDate(),offset=(new Date(Date.UTC(year,month-1,1)).getUTCDay()+6)%7;const headers=lang==='es'?['L','M','X','J','V','S','D']:['M','T','W','T','F','S','S'];$('#calendar').innerHTML=`<div class="agenda-calendar-top"><strong>${tr(mode.endsWith('11')?'nov':'dec')} ${year}</strong><button id="whole-month">${tr('allMonth')}</button></div><div class="agenda-weekdays">${headers.map(x=>`<span>${x}</span>`).join('')}</div><div class="agenda-days">${'<span></span>'.repeat(offset)}${Array.from({length:days},(_,i)=>{const d=mode+'-'+String(i+1).padStart(2,'0'),count=list.filter(e=>occursOn(e,d)).length;return `<button data-day="${d}" aria-label="${dateText(d,true)} · ${count} ${tr('functions')}" aria-pressed="${chosenDay===d}" ${d===localDate()?'aria-current="date"':''}><span>${i+1}</span><small>${count||'·'}</small></button>`;}).join('')}</div>`;}
function render(){if(dialog.open)return;const now=new Date(),today=localDate(now),list=filtered();$('.agenda-topics').setAttribute('aria-label',tr('topicLabel'));document.querySelectorAll('[data-plan]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.plan===plan)));$('#agenda-clock').textContent=new Intl.DateTimeFormat(locale(),{timeZone:TIME_ZONE,weekday:'long',day:'numeric',month:'long',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(now)+' · CDMX';document.querySelectorAll('[data-mode]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.mode===mode)));calendar(list);let chosen=mode==='today'||mode==='now'?list.filter(e=>occursOn(e,today)):list.filter(e=>chosenDay?occursOn(e,chosenDay):inMonth(e,mode));chosen.sort((a,b)=>(a.date.localeCompare(b.date))||((a.startTime||a.doorsTime||'99:99').localeCompare(b.startTime||b.doorsTime||'99:99')));$('#agenda-summary').textContent=`${agenda.length} ${tr('published')} · ${tr('review')}`;$('#agenda-empty-range').hidden=today>='2026-11-01'&&today<='2026-12-31';if(mode==='now'){const current=chosen.filter(e=>isNow(e,now)),rest=chosen.filter(e=>!isNow(e,now));rest.sort((a,b)=>Number(eventState(b,now)==='upcoming')-Number(eventState(a,now)==='upcoming'));$('#agenda-result').innerHTML=`<section><div class="agenda-section-title"><h2><i class="rec-dot" aria-hidden="true"></i> ${tr('liveHeading')}</h2><span>${current.length}</span></div>${current.length?`<div class="agenda-grid">${current.map(e=>card(e,now)).join('')}</div>`:`<div class="agenda-empty"><h3>${tr('noLive')}</h3><p>${tr('noLiveText')}</p></div>`}</section><section><div class="agenda-section-title"><h2>${tr('later')}</h2><button data-switch-today>${tr('today')} ↗</button></div>${rest.length?`<div class="agenda-grid">${rest.slice(0,6).map(e=>card(e,now)).join('')}</div>`:`<p class="agenda-muted">${tr('noToday')}</p>`}</section>`;$('#agenda-more').hidden=true;return;}$('#agenda-result').innerHTML=`<div class="agenda-section-title"><h2>${chosenDay?`${tr('selected')} ${dateText(chosenDay)}`:mode==='today'?`${tr('today')} · ${dateText(today)}`:`${tr(mode.endsWith('11')?'nov':'dec')} 2026`}</h2><span>${chosen.length} ${tr('functions')}</span></div>${chosen.length?`<div class="agenda-grid">${chosen.slice(0,limit).map(e=>card(e,now)).join('')}</div>`:`<div class="agenda-empty"><h3>${tr('empty')}</h3><button id="clear-agenda">${tr('reset')}</button></div>`}`;$('#agenda-more').hidden=chosen.length<=limit;}
function open(html){lastFocus=document.activeElement;$('#agenda-dialog-body').innerHTML=html;dialog.showModal();$('#close-agenda').focus();}
function close(){const id=lastFocus?.dataset.event;dialog.close();render();(id?document.querySelector('[data-event="'+id+'"]'):lastFocus)?.focus();}
function detail(e){open(`${preview(e,true)}<span class="agenda-status">${tr(e.category)}</span><h2 id="agenda-dialog-title">${esc(e.name)}</h2><p class="agenda-detail-date">${dateText(e.date,true)}${e.through?' — '+dateText(e.through,true):''}</p><p class="agenda-detail-hours">${esc(schedule(e))}</p><p>${esc(e.venue)} · ${esc(e.address)} · ${esc(e.area)}</p>${e.endApproximate?`<p class="agenda-muted">${tr('approxNote')}</p>`:''}${e.usualHours?`<p class="agenda-muted">${tr('usualNote')}</p>`:''}${e.note?`<p>${esc(e.note[lang])}</p>`:''}${e.status==='postponed'?`<p class="agenda-alert">${tr('postponed')}</p>`:''}${e.availability?`<p class="agenda-alert">${e.availability==='soldout'?tr('soldout'):tr('registered')}</p>`:''}${e.price?`<p>${tr('price')}: ${esc(e.price)}</p>`:''}<p class="agenda-muted">${tr('timeNote')}</p><a class="button agenda-source-button" href="${esc(e.source)}" target="_blank" rel="noopener noreferrer">${tr('source')} ↗</a><details><summary>${tr('sources')}</summary><ul>${[...new Set([e.source,...(e.references||[])])].map(u=>`<li><a href="${esc(u)}" target="_blank" rel="noopener noreferrer">${esc(new URL(u).hostname)} ↗</a></li>`).join('')}</ul><small>${tr('checked')} ${dateText(e.checked,true)}</small></details>`);}
document.addEventListener('click',ev=>{const b=ev.target.closest('[data-event],[data-mode],[data-day],[data-switch-today],[data-plan]');if(b?.dataset.plan){plan=b.dataset.plan;$('#agenda-type').value='';limit=24;render();}if(b?.dataset.event){const e=agenda.find(x=>x.id===b.dataset.event);if(e)detail(e);}if(b?.dataset.mode){mode=b.dataset.mode;chosenDay='';limit=24;render();}if(b?.dataset.day){chosenDay=b.dataset.day;limit=24;render();}if(b?.hasAttribute('data-switch-today')){mode='today';render();}if(ev.target.closest('#whole-month')){chosenDay='';limit=24;render();}if(ev.target.closest('#clear-agenda')){plan='all';$('#agenda-search').value='';['agenda-type','agenda-venue','agenda-area'].forEach(id=>$('#'+id).value='');render();}});
$('#agenda-search').oninput=()=>{limit=24;render();};['agenda-type','agenda-venue','agenda-area'].forEach(id=>$('#'+id).onchange=()=>{if(id==='agenda-type')plan='all';limit=24;render();});$('#agenda-more').onclick=()=>{limit+=24;render();};$('#language').onchange=()=>{lang=$('#language').value;try{sessionStorage.setItem('lavita-language',lang);}catch{}interfaceText();};$('#close-agenda').onclick=close;dialog.addEventListener('cancel',e=>{e.preventDefault();close();});dialog.addEventListener('keydown',e=>{if(e.key!=='Tab')return;const list=[...dialog.querySelectorAll('a[href],button,summary')].filter(x=>x.getClientRects().length),first=list[0],last=list.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}});
$('#agenda-coverage').onclick=()=>open(`<h2 id="agenda-dialog-title">${tr('coverage')}</h2><p>${tr('snapshot')}</p><p>${tr('refresh')}</p><p>${tr('review')}</p><ul>${agendaMeta.coverage.map(v=>{const e=agenda.find(e=>e.venue.includes(v)||v.includes(e.venue)||v.startsWith('ORIGINAL')&&e.venue.includes('Pinos')||v.startsWith('CONFE')&&e.venue.includes('Salle'));return `<li>${e?`<a href="${esc(e.source)}" target="_blank" rel="noopener noreferrer">${esc(v)} ↗</a>`:esc(v)}</li>`;}).join('')}</ul>`);
$('#profile-button').onclick=()=>{const p=member();open(`<h2 id="agenda-dialog-title">${tr('profile')}</h2><p>${esc(p.name)} · ${p.points} ${tr('points')}</p>`);};
interfaceText();let lastMinute=Math.floor(Date.now()/60000);setInterval(()=>{const minute=Math.floor(Date.now()/60000);if(minute!==lastMinute){lastMinute=minute;render();}},1000);window.addEventListener('focus',render);document.addEventListener('visibilitychange',()=>{if(!document.hidden)render();});
